-- Add triggered_by_user_id and title columns to ai_workforce_queue (MB-147).
-- These were missing from the original schema:
--   - triggered_by_user_id: the user who initiated the task. Nullable because
--     cron/webhook-triggered runs have no human user (cron has routine.created_by
--     via trigger_meta; webhook is system-initiated).
--   - title: human-friendly task label shown in the queue UI. Auto-generated
--     by Haiku from input.prompt at enqueue time. Nullable so the row exists
--     before title-gen completes (it runs as a fire-and-forget after()).

ALTER TABLE ai_workforce_queue
  ADD COLUMN triggered_by_user_id uuid REFERENCES users(id) ON DELETE SET NULL,
  ADD COLUMN title text;

CREATE INDEX idx_ai_workforce_queue_triggered_by
  ON ai_workforce_queue (triggered_by_user_id)
  WHERE triggered_by_user_id IS NOT NULL;

COMMENT ON COLUMN ai_workforce_queue.triggered_by_user_id IS
  'User who initiated the task. Null for cron (see trigger_meta.routine_id) and webhook triggers.';
COMMENT ON COLUMN ai_workforce_queue.title IS
  'Human-friendly task label. Auto-generated by Haiku from input.prompt shortly after enqueue.';
